var q=rest.indexOf('?');
if(q>=0) rest=rest.substring(0,q);
var sl=rest.lastIndexOf('/');
if(sl>=0) rest=rest.substring(0,sl);
try{ return decodeURIComponent(rest); }catch(e){ return rest; }
}
