// --- 发现页：榜单/分类（网页版 HTML 解析）---
function HG_explore(JV, path, page){
var u='https://hongguoduanju.com/'+path;
var h={'User-Agent':'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Mobile Safari/537.36','Referer':'https://hongguoduanju.com/'};
var html=String(JV.ajax(u+',{"headers":'+JSON.stringify(h)+'}'));
var doc=Packages.org.jsoup.Jsoup.parse(html);
var as=doc.select('a[href^=/detail?series_id=]');
var out=[],seen={};
for(var i=0;i<as.size();i++){
var a=as.get(i);
var href=String(a.attr('href'));
var mm=href.match(/series_id=([0-9]+)/);
if(!mm) continue;
var sid=mm[1];
if(seen[sid]) continue;
seen[sid]=1;
var name=String(a.attr('aria-label')).replace(/^查看/,'').replace(/封面$/,'');
if(!name){
var img=a.select('img');
if(img.size()>0) name=String(img.get(0).attr('alt')).replace(/封面$/,'');
}
if(!name) name='短剧'+sid.substring(0,6);
var cover='';
var img2=a.select('img');
if(img2.size()>0) cover=String(img2.get(0).attr('src'));
out.push(JSON.stringify({name:name,author:'红果短剧',kind:'',intro:'',coverUrl:cover,
bookUrl:'https://api5-normal-sinfonlineb.fqnovel.com/detail?series_id='+sid}));
}
return out;
}
